import {capturePhoto} from './camera-capture.js';
import {bindCallResizer} from './call-resizer.js';
import './call-workspace.css';
import {createMovies} from './movies.js';
import {createProfiles} from './profiles.js';
import {editAvatar} from './avatar-editor.js';
import {accountPopover} from './account-popover.js';
import {rememberAccount,savedAccounts,switchAccount,addAccount,forgetAccount} from './accounts.js';
import {apiURL,assetURL,socketURL,API_ORIGIN} from './config.js';
import './style.css';
import './repairs.css';
import './vela-cinejoy.css';
import {auth,onAuthStateChanged,signInWithEmailAndPassword,createUserWithEmailAndPassword,sendPasswordResetEmail,signOut} from './auth.js';
import {icon,button} from './icons.js';
import {escape as e,avatar,time,date,bytes,online,messageHTML,mediaError,renderEmoji,setExpressionLinks} from './util.js';
import {CallEngine,QUALITY} from './call.js';
const $=s=>document.querySelector(s),root=$('#app'),layers=$('#layers');
const S={user:null,friends:[],conversations:[],blocks:[],active:null,view:'friends',tab:'online',messages:[],more:false,query:'',reply:null,upload:null,outbox:[],prefs:{},incoming:null};
let disposeCallResizer;
let engine,live,liveRetry,liveGeneration=0,liveFailures=0,refreshTimer,refreshing=false,dirty=false,typingTimer,lastTyping=0,loadingMessages=false,authMode='login',refreshId=0,messageId=0,callLayout='grid',focusTile=null;
const profiles=createProfiles({api,modal,toast,self:()=>S.user,chatWith,editSelf:()=>profile(S.user.uid)});
const movies=createMovies({api,modal,toast,self:()=>S.user,conversation:()=>{const c=S.conversations.find(c=>c.id===(engine?.info?.conversation||S.active));return c?{id:c.id,name:title(c)}:null},getCall:()=>engine,onStageChange:key=>{if(key!==undefined)focusTile=key;updateCall()}});
const profileAvatar=(p,size='')=>'<button class="avatar-profile-button" data-profile="'+e(p.uid)+'" aria-label="View '+e(p.name||p.handle)+' profile">'+avatar(p,size)+'</button>';
const defaults={muted:false,volume:100,input:'',output:'',camera:'',noise:true,echo:true,gain:true,mirror:true,theme:'onyx',density:'default',reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,sounds:true,textSize:16,inputVolume:100,inputProfile:'custom',gridView:false,showNonVideo:true};
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;$('#toasts').append(el);setTimeout(()=>el.remove(),5500);}
function sound(name,loop=false){if(!S.prefs.sounds)return;const audio=new Audio(assetURL('sounds/'+name+'.mp3'));audio.loop=loop;audio.volume=.35;audio.play().catch(()=>{});return audio;}
async function api(path,{method='GET',...options}={}){const token=await auth.currentUser?.getIdToken();const headers={...options.headers,...(token?{Authorization:'Bearer '+token}:{})};let body=options.body;if(body&&!(body instanceof Blob)&&typeof body!=='string'){headers['Content-Type']='application/json';body=JSON.stringify(body)}const res=await fetch(apiURL(path),{...options,method,body,headers});const data=await res.json().catch(()=>({}));if(!res.ok)throw Object.assign(new Error(data.error||'Request failed. Retry shortly.'),{status:res.status});return data;}
const act=fn=>Promise.resolve().then(fn).catch(error=>toast(error.message));
const active=()=>S.conversations.find(c=>c.id===S.active);
const user=uid=>S.user?.uid===uid?S.user:S.conversations.flatMap(c=>c.members).find(m=>m.uid===uid)||S.friends.find(f=>f.uid===uid)||{uid,name:'User',handle:''};
const title=c=>c?.name||(c?.kind==='direct'?c.members.find(m=>m.uid!==S.user.uid)?.name:c?.members.filter(m=>m.uid!==S.user.uid).map(m=>m.name).join(', '))||'Conversation';
const other=c=>c?.members.find(m=>m.uid!==S.user.uid)||S.user;
function readStored(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value&&typeof value===typeof fallback&&Array.isArray(value)===Array.isArray(fallback)?value:fallback}catch{return fallback}}
function prefs(){S.prefs={...defaults,...readStored('pixl.settings.'+S.user.uid,{})};applyPrefs();}
function applyPrefs(){document.documentElement.dataset.theme=S.prefs.theme;document.documentElement.dataset.density=S.prefs.density;document.documentElement.dataset.motion=S.prefs.reduced?'reduced':'full';document.documentElement.style.setProperty('--chat-font',S.prefs.textSize+'px');}
function savePrefs(){localStorage.setItem('pixl.settings.'+S.user.uid,JSON.stringify(S.prefs));applyPrefs();if(engine){engine.settings=S.prefs;engine.muted=S.prefs.muted;engine.mic?.getAudioTracks().forEach(t=>t.enabled=!engine.muted);}updateDock();updateCall();}
function authScreen(){
 root.innerHTML=`<main class="auth-screen"><a class="wordmark" href="${assetURL('')}">${icon('chat',30)}<strong>Vela</strong></a><form class="auth-card" id="auth-form"><h1>${authMode==='signup'?'Create an account':'Welcome back!'}</h1><p>${authMode==='signup'?'Choose your username to get started.':'Sign in with your existing account.'}</p>${authMode==='signup'?'<label>DISPLAY NAME<input name="name" autocomplete="name" maxlength="48" required></label>':''}<label>${authMode==='signup'?'USERNAME':'USERNAME OR EMAIL'}<input id="login-handle" name="handle" autocomplete="username" autocapitalize="none" spellcheck="false" maxlength="100" required></label><label>PASSWORD<input name="password" type="password" autocomplete="${authMode==='signup'?'new-password':'current-password'}" minlength="6" required></label><p class="form-error" role="alert"></p><button class="primary wide" type="submit">${authMode==='signup'?'Create Account':'Log In'}</button><p class="auth-switch">${authMode==='signup'?'Already have an account?':'Need an account?'} <button type="button" data-action="auth-toggle">${authMode==='signup'?'Log in':'Register'}</button></p><button class="text-button" type="button" data-action="password-reset">Forgot your password?</button></form></main>`;
 $('#auth-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,b=new FormData(form),handle=String(b.get('handle')).trim().toLowerCase();const email=handle.includes('@')?handle:handle+'@users.connections.invalid';if(authMode==='signup'&&!/^[a-z0-9_]{3,20}$/.test(handle)){form.querySelector('.form-error').textContent='Use 3–20 letters, numbers or underscores.';return;}form.querySelector('[type=submit]').disabled=true;try{sessionStorage.setItem('pixl.signup',JSON.stringify({name:b.get('name')||handle,handle:handle.split('@')[0]}));await (authMode==='signup'?createUserWithEmailAndPassword:signInWithEmailAndPassword)(auth,email,String(b.get('password')));}catch(error){form.querySelector('.form-error').textContent=({'auth/invalid-credential':'That username or password is incorrect.','auth/email-already-in-use':'That username already exists. Sign in instead.','auth/too-many-requests':'Too many attempts. Please try again later.','auth/network-request-failed':'Cannot reach sign-in. Check your connection.'})[error.code]||error.message;form.querySelector('[type=submit]').disabled=false;}};
}
async function startup(){
 try{const data=await api('/me');S.user=data.user;if(!S.user){const saved=JSON.parse(sessionStorage.getItem('pixl.signup')||'{}');S.user=(await api('/me',{method:'PUT',body:{name:saved.name||auth.currentUser.email.split('@')[0],handle:saved.handle||auth.currentUser.email.split('@')[0]}})).user;}rememberAccount(S.user).catch(()=>{});prefs();S.outbox=readStored('pixl.outbox.'+S.user.uid,[]);shell();engine=new CallEngine({api,user:S.user,settings:S.prefs});engine.addEventListener('change',updateCall);engine.addEventListener('error',ev=>toast(ev.detail));await api('/session',{method:'POST'});await refresh();connectLive();refreshTimer=setInterval(()=>refresh().catch(()=>{}),30000);flushOutbox();}catch(error){root.innerHTML=`<main class="auth-screen"><div class="auth-card"><h1>Connection interrupted</h1><p>${e(error.message)}</p><button class="primary" data-action="reload">Try again</button></div></main>`;}
}
function shell(){disposeCallResizer?.();root.innerHTML=`<div class="app-shell"><div class="top-strip"><span>${icon('users',16)} <span id="desktop-page-title">Friends</span></span><div>${button('inbox','Inbox','inbox')}${button('info','Help','help')}</div></div><nav class="server-rail" aria-label="Home and groups"><button class="rail-icon home selected" data-action="friends" data-tip="Direct Messages" aria-label="Direct Messages">${icon('chat',26)}</button><div class="rail-divider"></div><div id="rail-groups"></div><button class="rail-icon add" data-action="new-group" data-tip="Create Group" aria-label="Create Group">${icon('plus',25)}</button></nav><aside class="sidebar"><button class="quick-find" data-action="quick-search">Find or start a conversation <kbd>${/Mac|iPhone|iPad/.test(navigator.platform)?'⌘':'Ctrl'} K</kbd></button><nav class="home-navigation"><button data-action="friends">${icon('users')}<span>Friends</span><b id="pending-count"></b></button><button data-action="requests">${icon('inbox')}<span>Message Requests</span><b id="request-count"></b></button><button data-action="movies">${icon('film')}<span>Movies</span></button></nav><div class="dm-heading"><span>Direct Messages</span>${button('plus','Create Message','new-group')}</div><div id="dm-list" class="dm-list"></div><div id="voice-dock"></div><div id="account-dock"></div></aside><main class="workspace"><header id="workspace-header"></header><div class="connection-banner" id="connection-banner" hidden></div><section id="call-stage" aria-label="Call" hidden><div class="call-statusline"><span id="call-status"></span><div>${button('maximize','Expand Call','expand-call')}${button('more','More Call Options','call-more')}</div></div><div id="call-tiles" class="call-tiles"></div><div class="call-controls" id="call-controls"></div><div class="call-resizer" role="separator" aria-label="Resize call area" aria-orientation="horizontal" aria-valuenow="320" tabindex="0"><span></span></div></section><div id="main-content"></div></main><div id="incoming-call"></div><div id="remote-audios" hidden></div></div>`;disposeCallResizer=bindCallResizer($('#call-stage'),()=>{callLayout='grid';$('#call-stage').classList.remove('expanded')});render();}
function render(){if(S.view==='bookmarks')S.view='friends';if(!S.user||!$('#dm-list'))return;renderSidebar();renderHeader();renderContent();updateDock();updateCall();}
function renderSidebar(){
 const pending=S.friends.filter(f=>f.status==='pending'&&f.requested_by!==S.user.uid).length;$('#pending-count').textContent=pending||'';$('#request-count').textContent=pending||'';
 document.querySelectorAll('.home-navigation>button').forEach(b=>b.classList.toggle('selected',b.dataset.action===S.view||S.view==='friends'&&b.dataset.action==='friends'));
 $('#dm-list').innerHTML=S.conversations.map(c=>`<button class="dm-row ${S.active===c.id&&S.view==='chat'?'selected':''} ${c.unread?'unread':''}" data-open="${e(c.id)}">${c.kind==='group'?`<span class="avatar group">${icon('users')}</span>`:avatar(other(c))}<span class="dm-identity"><strong>${e(title(c))}</strong><small>${c.kind==='group'?c.members.length+' Members':e(c.preview||'')}</small></span>${c.unread?'<b class="badge">'+c.unread+'</b>':''}${c.call?icon('phone',15):''}</button>`).join('')||'<p class="sidebar-empty">Your conversations appear here.</p>';
 $('#rail-groups').innerHTML=S.conversations.filter(c=>c.kind==='group').map(c=>`<button class="rail-icon ${S.active===c.id?'selected':''}" data-open="${e(c.id)}" data-tip="${e(title(c))}" aria-label="${e(title(c))}">${e(title(c).slice(0,2).toUpperCase())}</button>`).join('');
}
function renderHeader(){if(S.view==='movies'){$('#desktop-page-title').textContent='Movies';$('#workspace-header').innerHTML='<div class="header-identity">'+icon('video')+'<strong>Movies</strong></div><div class="header-actions">'+button('close','Close Movies','friends')+'</div>';return}const c=active();const label=$('#desktop-page-title');if(label)label.textContent=S.view==='chat'?'Direct Messages':S.view==='requests'?'Message Requests':'Friends';$('#workspace-header').innerHTML=S.view==='chat'&&c?`<div class="header-identity">${button('menu','Show Navigation','mobile-nav')}${c.kind==='group'?icon('users'):profileAvatar(other(c),'small')}<strong>${e(title(c))}</strong><span class="muted">${c.kind==='group'?c.members.length+' members':'@'+e(other(c).handle)}</span></div><div class="header-actions">${c.call&&engine?.info?.id!==c.call.id?'<button class="join-active-call" data-action="join-existing-call">Join Call</button>':''}<span class="header-call-buttons">${button('phone','Start Voice Call','voice-call')}${button('video','Start Video Call','video-call')}</span>${button('pin','Pinned Messages','pins')}${button('users','Conversation Members','members')}${button('more','Conversation Options','conversation-more')}<div class="header-search">${icon('search',16)}<input id="message-search" placeholder="Search" aria-label="Search messages"></div></div>`:`<div class="header-identity">${button('menu','Show Navigation','mobile-nav')}${icon(S.view==='friends'?'users':S.view==='bookmarks'?'bookmark':'inbox')}<strong>${S.view==='friends'?'Friends':S.view==='bookmarks'?'Bookmarks':'Message Requests'}</strong>${S.view==='friends'?'<span class="header-divider"></span><nav class="friend-tabs" aria-label="Friends">'+[['online','Online'],['all','All'],['pending','Pending'],['add','Add Friend']].map(([id,label])=>`<button class="${S.tab===id?'selected':''} ${id==='add'?'primary':''}" data-tab="${id}">${label}${id==='pending'&&S.friends.some(f=>f.status==='pending')?'<b class="badge">'+S.friends.filter(f=>f.status==='pending').length+'</b>':''}</button>`).join('')+'</nav>':''}</div><div class="header-actions">${button('addUser','New Group DM','new-group')}</div>`;
 if($('#message-search'))$('#message-search').onkeydown=event=>{if(event.key==='Enter'){S.query=event.currentTarget.value.trim();loadMessages();}if(event.key==='Escape'){S.query='';event.currentTarget.value='';loadMessages();}};
}
function renderContent(){
 const content=$('#main-content');if(S.view==='movies'){content.className='movie-content';act(()=>movies.render(content));return}content.className=S.view==='chat'?'chat-content':'friends-content';
 if(S.view==='chat'){const c=active();if(!c){S.view='friends';return render();}content.innerHTML=`<div id="message-scroll" class="message-scroll"><button class="load-older" id="load-older" data-action="older" hidden>Load earlier messages</button><div class="conversation-start">${c.kind==='group'?'<div class="large-group">'+icon('users',42)+'</div>':avatar(other(c),'large')}<h1>${e(title(c))}</h1><p>This is the beginning of your conversation with ${e(title(c))}.</p></div><div id="messages"></div></div><div id="typing-label" class="typing-label"></div><form id="composer-form"><div id="reply-preview"></div><div id="upload-preview"></div><div class="composer">${button('plus','Attach a File','attach')}${button('camera','Take a Photo','take-photo')}<textarea id="composer" rows="1" maxlength="4000" placeholder="Message ${e(title(c))}" aria-label="Message ${e(title(c))}"></textarea><button type="button" class="icon-button composer-gif" data-action="gif" aria-label="Open GIF picker" data-tip="GIFs"><b>GIF</b></button>${button('sticker','Open sticker picker','sticker')}${button('emoji','Add Emoji','emoji')}<button class="icon-button send-button" aria-label="Send Message" type="submit">${icon('send')}</button><input id="file-input" type="file" hidden></div><div class="composer-hint"><span id="outbox-status"></span></div></form>`;
 $('#composer').value=localStorage.getItem('pixl.draft.'+S.user.uid+'.'+S.active)||'';$('#composer').oninput=ev=>{localStorage.setItem('pixl.draft.'+S.user.uid+'.'+S.active,ev.target.value);ev.target.style.height='auto';ev.target.style.height=Math.min(160,ev.target.scrollHeight)+'px';if(Date.now()-lastTyping>3000){lastTyping=Date.now();api('/conversations/'+encodeURIComponent(S.active)+'/typing',{method:'POST',body:{typing:true}}).catch(()=>{});}};
 $('#composer').onkeydown=ev=>{if(ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing){ev.preventDefault();$('#composer-form').requestSubmit();}if(ev.key==='Escape'&&S.reply){S.reply=null;renderReply();}};$('#composer-form').onsubmit=sendMessage;$('#file-input').onchange=ev=>{if(ev.target.files[0])uploadFile(ev.target.files[0]);};content.ondragover=ev=>{ev.preventDefault();content.classList.add('dragging')};content.ondragleave=()=>content.classList.remove('dragging');content.ondrop=ev=>{ev.preventDefault();content.classList.remove('dragging');if(ev.dataTransfer.files[0])uploadFile(ev.dataTransfer.files[0]);};renderMessages();renderReply();renderUpload();
 }else if(S.view==='bookmarks'){content.innerHTML='<div class="page-heading"><h2>Bookmarks</h2><p>Messages saved for you.</p></div><div id="bookmark-list"></div>';api('/bookmarks').then(data=>{$('#bookmark-list').innerHTML=data.messages.length?data.messages.map(m=>`<button class="bookmark-row" data-open="${e(m.conversation)}"><strong>${e(user(m.sender).name)}</strong><p>${e(m.text||'Attachment')}</p><small>${date(m.created)}</small></button>`).join(''):empty('bookmark','Save a message for later','Open a message’s menu and choose Bookmark Message.');}).catch(err=>toast(err.message));
 }else if(S.view==='requests'){renderRequests(content);}else renderFriends(content);
}
function empty(sym,title,description){return `<div class="empty-state"><div class="empty-symbol">${icon(sym,64)}</div><h2>${e(title)}</h2><p>${e(description)}</p></div>`;}
function renderFriends(content){
 if(S.tab==='add'){content.innerHTML=`<div class="add-friend"><h2>Add Friend</h2><p>You can add friends with their Vela username.</p><form id="add-friend-form"><input name="handle" autocomplete="off" placeholder="Enter a username" maxlength="20" required aria-label="Friend username"><button class="primary">Send Friend Request</button></form><p class="form-error" id="friend-result" role="status"></p></div>${empty('users','Make room for your people','Add a friend, send a message, or start a call.')}`;$('#add-friend-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget;form.querySelector('button').disabled=true;try{await api('/friends',{method:'POST',body:{handle:new FormData(form).get('handle')}});$('#friend-result').textContent='Friend request sent.';form.reset();await refresh();}catch(err){$('#friend-result').textContent=err.message;}finally{form.querySelector('button').disabled=false;}};return;}
 const list=S.friends.filter(f=>S.tab==='pending'?f.status==='pending':f.status==='accepted'&&(S.tab!=='online'||online({...f,status:f.presence})));content.innerHTML=`<section class="friends-list"><div class="list-search">${icon('search',20)}<input id="friends-search" placeholder="Search" aria-label="Search friends"></div><h2 class="eyebrow">${S.tab==='pending'?'Pending':S.tab==='all'?'All friends':'Online'} — ${list.length}</h2><div id="friends-rows">${list.map(f=>friendRow(f)).join('')||empty('users',S.tab==='online'?'No one’s online right now':S.tab==='pending'?'No pending requests':'Your friends belong here',S.tab==='online'?'You can still message friends from the All tab.':'Add someone by their username to get started.')}</div></section><aside class="active-now"><h2>Active Now</h2>${S.conversations.filter(c=>c.call).map(c=>`<button class="activity-card" data-open="${e(c.id)}"><span class="activity-icon">${icon('phone')}</span><strong>${e(title(c))}</strong><span>Call in progress</span></button>`).join('')||'<div class="quiet-state"><strong>It’s quiet for now…</strong><p>When a call starts, it will appear here.</p></div>'}</aside>`;$('#friends-search').oninput=ev=>{const value=ev.target.value.toLowerCase();document.querySelectorAll('.friend-row').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(value));};
}
function friendRow(f){const pending=f.status==='pending',incoming=f.requested_by!==S.user.uid;return `<div class="friend-row" data-friend="${e(f.uid)}">${profileAvatar({...f,status:f.presence})}<button class="friend-name" data-chat="${e(f.uid)}"><strong>${e(f.name)}</strong><span>${pending?(incoming?'Incoming Friend Request':'Outgoing Friend Request'):(online({...f,status:f.presence})?f.presence==='dnd'?'Do Not Disturb':f.presence==='idle'?'Idle':'Online':'Offline')}</span></button><div class="row-actions">${pending?`${incoming?button('check','Accept Friend Request','accept:'+f.id):''}${button('close',incoming?'Ignore Friend Request':'Cancel Friend Request',(incoming?'decline:':'cancel:')+f.id)}`:`<button class="round-action" data-chat="${e(f.uid)}" aria-label="Message ${e(f.name)}" data-tip="Message">${icon('chat')}</button><button class="round-action" data-friend-menu="${e(f.uid)}" aria-label="More options for ${e(f.name)}" data-tip="More">${icon('more')}</button>`}</div></div>`;}
function renderRequests(content){const incoming=S.friends.filter(f=>f.status==='pending'&&f.requested_by!==S.user.uid);content.innerHTML=`<section class="request-page"><h2>Pending Requests — ${incoming.length}</h2><p>Accept a friend request to start messaging and calling.</p>${incoming.map(friendRow).join('')||empty('inbox','You’re all caught up','New requests will appear here.')}</section>`;}
async function refresh(){if(refreshing){dirty=true;return}refreshing=true;try{const data=await api('/state');if(!S.user)return;S.user=data.user;S.friends=data.friends;S.conversations=data.conversations;S.blocks=data.blocks;renderSidebar();updateDock();if(S.view!=='chat'&&S.view!=='movies'&&S.tab!=='add')renderContent();if(S.view==='chat'){renderHeader();renderReadReceipts();}const calls=S.conversations.map(c=>c.call).filter(Boolean);const incoming=calls.find(c=>c.caller!==S.user.uid&&c.status==='ringing'&&c.created>Date.now()-90000&&engine?.info?.id!==c.id);if(incoming&&!sessionStorage.getItem('pixl.dismiss.'+incoming.id))showIncoming(incoming);else if(!incoming)hideIncoming();}finally{refreshing=false;if(dirty){dirty=false;refresh();}}}
async function openChat(cid){if(S.active===cid&&S.view==='chat'){$('#composer')?.focus();return}document.querySelectorAll("dialog[open]").forEach(d=>d.close());S.active=cid;S.view='chat';S.query='';S.reply=null;S.upload=null;S.messages=[];render();document.body.classList.remove('nav-open');$('#composer')?.focus();const loading=loadMessages();api('/conversations/'+encodeURIComponent(cid)+'/read',{method:'POST'}).catch(()=>{});api('/movie-rooms/'+encodeURIComponent(cid)).then(room=>movies.receive(room,cid)).catch(()=>{});await loading;}
async function chatWith(uid){const result=await api('/conversations',{method:'POST',body:{members:[uid]}});await refresh();await openChat(result.id);return active();}
async function loadMessages(older=false){if(!S.active)return;if(loadingMessages){messageId++;return;}loadingMessages=true;const cid=S.active,scroll=$('#message-scroll'),oldHeight=scroll?.scrollHeight,oldTop=scroll?.scrollTop;try{const result=await api('/conversations/'+encodeURIComponent(cid)+'/messages'+(older?'?before='+S.messages[0]?.created:S.query?'?q='+encodeURIComponent(S.query):''));if(cid!==S.active)return;await hydrateFiles(result.messages);if(cid!==S.active)return;S.messages=older?[...result.messages,...S.messages]:result.messages;S.more=result.more;renderMessages();if(older&&scroll)scroll.scrollTop=oldTop+scroll.scrollHeight-oldHeight;}finally{loadingMessages=false;if(messageId){messageId=0;loadMessages();}}}
function renderMessages(){const target=$('#messages');if(!target)return;const scroll=$('#message-scroll'),bottom=scroll.scrollHeight-scroll.scrollTop-scroll.clientHeight<180;const pending=S.outbox.filter(m=>m.conversation===S.active&&!S.messages.some(x=>x.id===m.id));let day='';target.innerHTML=[...S.messages,...pending].map((m,index,all)=>{const sender=user(m.sender),label=date(m.created),prior=all[index-1],grouped=prior&&prior.sender===m.sender&&m.created-prior.created<300000&&date(prior.created)===label;let separator=day!==label?`<div class="date-divider"><span>${label}</span></div>`:'';day=label;const reply=m.reply_to?all.find(x=>x.id===m.reply_to):null;const reactions=new Map();for(const r of m.reactions||[]){if(!reactions.has(r.emoji))reactions.set(r.emoji,[]);reactions.get(r.emoji).push(r.uid);}return `${separator}<article class="message ${grouped?'grouped':''} ${m.failed?'failed':''} ${m.pending?'pending':''}" data-message="${e(m.id)}" tabindex="0">${grouped?`<span class="mini-time" title="${e(new Date(m.created).toLocaleString())}">${time(m.created)}</span>`:profileAvatar(sender)}<div class="message-body">${!grouped?`<div class="message-heading"><button data-profile="${e(sender.uid)}">${e(sender.name)}</button><time title="${e(new Date(m.created).toLocaleString())}">${time(m.created)}</time>${m.pinned?icon('pin',12):''}</div>`:''}${m.reply_to?`<div class="reply-context">${icon('reply',14)}<span>${e(reply?user(reply.sender).name+': '+reply.text:'Original message')}</span></div>`:''}<div class="message-text">${m.deleted?'<em class="muted">Message deleted</em>':messageHTML(m.text)}</div>${m.edited?'<small class="edited">(edited)</small>':''}${m.attachment?attachment(m.attachment):''}<div class="reactions">${[...reactions].map(([emoji,uids])=>`<button class="${uids.includes(S.user.uid)?'own':''}" data-reaction="${e(m.id)}" data-emoji="${emoji}" title="${uids.map(uid=>user(uid).name).join(', ')}">${emoji} <span>${uids.length}</span></button>`).join('')}</div>${m.failed?`<button class="retry" data-action="retry:${e(m.id)}">Failed to send · Retry</button>`:m.pending?'<small class="delivery">Sending…</small>':''}</div>${!m.deleted?`<div class="message-toolbar">${button('emoji','Add Reaction','react:'+m.id)}${button(m.sender===S.user.uid?'edit':'reply',m.sender===S.user.uid?'Edit Message':'Reply',(m.sender===S.user.uid?'edit:':'reply:')+m.id)}${button('forward','Forward Message','forward:'+m.id)}${button('more','More Message Actions','message-menu:'+m.id)}</div>`:''}</article>`;}).join('');renderEmoji(target);renderReadReceipts();$('#load-older').hidden=!S.more;if(bottom||!S.messages.length)scroll.scrollTop=scroll.scrollHeight;}
function renderReadReceipts(){document.querySelectorAll('.message-receipt').forEach(el=>el.remove());if(S.view!=='chat')return;const mine=[...S.messages].reverse().find(m=>m.sender===S.user.uid&&!m.deleted);if(!mine)return;const article=[...document.querySelectorAll('[data-message]')].find(el=>el.dataset.message===mine.id);if(!article)return;const people=active()?.members.filter(p=>p.uid!==S.user.uid)||[],readers=people.filter(p=>p.last_read>=mine.created);const receipt=document.createElement('span');receipt.className='message-receipt'+(readers.length?' is-read':'');receipt.textContent=readers.length?(active().kind==='direct'?'Read':'Read by '+readers.map(p=>p.name).join(', ')):'Sent';receipt.title=readers.length?'Read by '+readers.map(p=>p.name).join(', '):'Sent';article.querySelector('.message-body').append(receipt);}
async function hydrateFiles(messages){const ids=[...new Set(messages.flatMap(m=>[...(m.text||'').matchAll(/<:[a-zA-Z0-9_]{2,32}:([a-zA-Z0-9-]+)>/g)].map(x=>x[1]).concat(m.attachment?.expressionId?[m.attachment.expressionId]:[])))];if(ids.length){const expressions={links:{}};for(let offset=0;offset<ids.length;offset+=100)Object.assign(expressions.links,(await api('/expression-links',{method:'POST',body:{ids:ids.slice(offset,offset+100)}})).links);setExpressionLinks(expressions.links);for(const m of messages)if(m.attachment?.expressionId)m.attachment.url=expressions.links[m.attachment.expressionId];}const attachments=messages.map(m=>m.attachment).filter(a=>a&&!a.kind);if(!attachments.length)return;const data=await api('/file-links',{method:'POST',body:{ids:attachments.map(a=>a.id)}});for(const attachment of attachments)attachment.url=data.links[attachment.id];}
function attachment(a){if(a.kind==='sticker'||a.kind==='emoji')return '<img class="'+(a.kind==='sticker'?'sticker-attachment':'custom-emoji-attachment')+'" src="'+e(a.url||'')+'" alt="'+e(a.name)+'">';const src=a.url||apiURL('/files/'+encodeURIComponent(a.id));if(a.type.startsWith('image/'))return `<button class="image-attachment" data-image="${e(src)}" aria-label="View ${e(a.name)}"><img src="${src}" alt="${e(a.name)}" loading="lazy"></button>`;if(a.type.startsWith('video/'))return `<video class="media-attachment" src="${src}" controls playsinline preload="metadata"></video>`;if(a.type.startsWith('audio/'))return `<audio src="${src}" controls preload="metadata"></audio>`;return `<a class="file-attachment" href="${src}" download="${e(a.name)}">${icon('file',28)}<span><strong>${e(a.name)}</strong><small>${bytes(a.size)}</small></span></a>`;}
function persistOutbox(){localStorage.setItem('pixl.outbox.'+S.user.uid,JSON.stringify(S.outbox));}
async function sendMessage(event){event.preventDefault();const input=$('#composer'),text=input.value.trim();if(!text&&!S.upload)return;const message={id:crypto.randomUUID(),conversation:S.active,sender:S.user.uid,text,upload:S.upload?.id,attachment:S.upload,reply_to:S.reply?.id,created:Date.now(),pending:true};S.outbox.push(message);persistOutbox();input.value='';input.style.height='auto';localStorage.removeItem('pixl.draft.'+S.user.uid+'.'+S.active);S.reply=null;S.upload=null;renderReply();renderUpload();renderMessages();$('#message-scroll').scrollTop=$('#message-scroll').scrollHeight;await flushOutbox();}
let flushing=false;
async function flushOutbox(){if(flushing||!S.user||!navigator.onLine)return;flushing=true;try{for(const m of [...S.outbox]){try{await api('/conversations/'+encodeURIComponent(m.conversation)+'/messages',{method:'POST',body:{id:m.id,text:m.text,upload:m.upload,replyTo:m.reply_to}});S.outbox=S.outbox.filter(x=>x.id!==m.id);persistOutbox();if(m.conversation===S.active)await loadMessages();}catch(err){m.failed=true;m.pending=false;persistOutbox();renderMessages();if(err.status===401)break;}}}finally{flushing=false;}}
async function takeChatPhoto(){const cid=S.active;if(!cid)return;await capturePhoto({modal,stream:engine?.camera,settings:S.prefs,onSend:async file=>{const result=await api('/uploads',{method:'POST',headers:{'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)},body:file});await hydrateFiles([{attachment:result.upload}]);const message={id:crypto.randomUUID(),conversation:cid,sender:S.user.uid,text:'',upload:result.upload.id,attachment:result.upload,created:Date.now(),pending:true};S.outbox.push(message);persistOutbox();if(S.active===cid)renderMessages();await flushOutbox();if(S.outbox.some(m=>m.id===message.id))toast('Photo queued. It will retry when the connection returns.')}})}
async function uploadFile(file){if(file.size>25*1024*1024)return toast('Files can be up to 25 MB.');const cid=S.active;$('#upload-preview').innerHTML='<div class="upload-progress">Uploading '+e(file.name)+'…</div>';try{const result=await api('/uploads',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file});if(cid!==S.active)return toast('Upload finished. Open the original conversation to attach it again.');S.upload=result.upload;await hydrateFiles([{attachment:S.upload}]);renderUpload();}catch(err){renderUpload();toast(err.message);}}
function renderUpload(){if($('#upload-preview'))$('#upload-preview').innerHTML=S.upload?`<div class="upload-progress">${icon('file')}<span>${e(S.upload.name)} · ${bytes(S.upload.size)}</span>${button('close','Remove Attachment','remove-upload')}</div>`:'';}
function renderReply(){if($('#reply-preview'))$('#reply-preview').innerHTML=S.reply?`<div class="reply-preview">Replying to <strong>${e(user(S.reply.sender).name)}</strong><span>${e(S.reply.text.slice(0,100))}</span>${button('close','Cancel Reply','cancel-reply')}</div>`:'';}
function updateDock(){if(!$('#account-dock')||!S.user)return;$('#account-dock').innerHTML=`<button class="self-profile" data-action="self-profile" aria-label="Manage profile and status" aria-haspopup="dialog" aria-expanded="${!!accountCard}">${avatar(S.user)}<span><strong>${e(S.user.name)}</strong><small>${e(S.user.handle)}</small></span></button><div class="dock-controls"><div class="dock-split">${button(S.prefs.muted?'micOff':'mic',S.prefs.muted?'Unmute':'Mute','mute',S.prefs.muted?'muted-control':'')}${button('down','Input Options','input-options','device-chevron')}</div><div class="dock-split">${button(engine?.deafened?'deaf':'headphones',engine?.deafened?'Undeafen':'Deafen','deafen')}${button('down','Output Options','output-options','device-chevron')}</div>${button('settings','User Settings','settings')}</div>`;}
async function connectLive(){clearTimeout(liveRetry);if(!S.user||!navigator.onLine)return connectionStatus();const generation=++liveGeneration,prior=live;if(prior){prior.onclose=null;prior.close()}try{const uid=S.user.uid,{ticket}=await api('/ticket',{method:'POST',body:{scope:'live'}});if(S.user?.uid!==uid||generation!==liveGeneration)return;const socket=live=new WebSocket(socketURL('/live',ticket));socket.onopen=()=>{if(generation!==liveGeneration)return socket.close();liveFailures=0;S.live=true;connectionStatus();};socket.onmessage=ev=>{if(ev.data==='pong')return;let data;try{data=JSON.parse(ev.data)}catch{return}if(data.type==='typing'&&data.uid!==S.user.uid&&data.conversation===S.active){$('#typing-label').textContent=data.typing?user(data.uid).name+' is typing…':'';clearTimeout(typingTimer);typingTimer=setTimeout(()=>{if($('#typing-label'))$('#typing-label').textContent='';},4500);}if(data.type==='movie-state')act(()=>movies.receive(data,data.conversation));if(['message','message-updated'].includes(data.type)){if(data.conversation===S.active){loadMessages();if(document.visibilityState==='visible')api('/conversations/'+encodeURIComponent(S.active)+'/read',{method:'POST'}).catch(()=>{});}if(data.type==='message'&&data.sender!==S.user.uid&&S.user.status!=='dnd')sound('message1');refresh();}if(['refresh','read','call','call-ended','call-updated'].includes(data.type)){refresh();if(data.type==='call-ended'&&engine?.info?.id===data.id&&(!data.legacyOnly||!engine.device))engine.leave();}};socket.onclose=()=>{if(generation!==liveGeneration)return;S.live=false;if(!S.user)return;connectionStatus();const delay=Math.min(12000,1000*2**Math.min(liveFailures++,4));liveRetry=setTimeout(()=>api('/session',{method:'POST'}).then(connectLive).catch(()=>{liveRetry=setTimeout(connectLive,delay)}),delay);};socket.onerror=()=>socket.close();}catch{if(S.user&&generation===liveGeneration){S.live=false;connectionStatus();liveRetry=setTimeout(connectLive,Math.min(12000,1000*2**Math.min(liveFailures++,4)));}}}
setInterval(()=>{if(live?.readyState===1)live.send('ping');},30000);
function connectionStatus(){const el=$('#connection-banner');if(!el)return;el.hidden=navigator.onLine&&live?.readyState===1;el.textContent=navigator.onLine?'Reconnecting to live updates…':'You’re offline. Messages will send when you reconnect.';}
function modal(title,html,{wide=false,onclose}={}){closeMenu();const dialog=document.createElement('dialog');dialog.setAttribute('aria-label',title);dialog.className='modal '+(wide?'wide-modal':'');dialog.innerHTML=`<header><h2>${e(title)}</h2><button class="icon-button" aria-label="Close">${icon('close')}</button></header><div class="modal-content">${html}</div>`;layers.append(dialog);dialog.querySelector('header button').onclick=()=>dialog.close();dialog.addEventListener('click',ev=>{if(ev.target===dialog){const r=dialog.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{onclose?.();dialog.remove();});dialog.showModal();return dialog;}
let menu,accountCard;
function closeMenu(){menu?.remove();menu=null;accountCard?.remove();accountCard=null;}
function popup(anchor,items){closeMenu();menu=document.createElement('div');menu.className='popover-menu';menu.setAttribute('role','menu');menu.innerHTML=items.map(item=>item==='-'?'<hr>':`<button role="${typeof item.checked==='boolean'?'menuitemcheckbox':'menuitem'}" ${typeof item.checked==='boolean'?'aria-checked="'+item.checked+'"':''} ${item.disabled?'disabled':''} data-menu="${e(item.id)}" class="${item.danger?'danger':''}">${item.icon?icon(item.icon,18):''}<span>${e(item.label)}</span>${typeof item.checked==='boolean'?'<i class="menu-checkbox '+(item.checked?'checked':'')+'">'+(item.checked?icon('check',14):'')+'</i>':''}</button>`).join('');layers.append(menu);const r=anchor.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(innerWidth-menu.offsetWidth-8,r.right-menu.offsetWidth))+'px';menu.style.top=Math.max(8,Math.min(innerHeight-menu.offsetHeight-8,r.bottom+6))+'px';menu.querySelectorAll('button').forEach(b=>b.onclick=()=>{const item=items.find(i=>i.id===b.dataset.menu);closeMenu();act(()=>item.run?.());});menu.querySelector('button:not(:disabled)')?.focus();menu.onkeydown=ev=>{const buttons=[...menu.querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement);if(ev.key==='ArrowDown'){ev.preventDefault();buttons[(i+1)%buttons.length].focus();}if(ev.key==='ArrowUp'){ev.preventDefault();buttons[(i-1+buttons.length)%buttons.length].focus();}};}
document.addEventListener('pointerdown',ev=>{if(menu&&!menu.contains(ev.target))closeMenu();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeMenu();if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){if(!S.user||document.querySelector('dialog[open]'))return;ev.preventDefault();quickSearch();}});
function quickSearch(){const dialog=modal('Find a conversation',`<div class="modal-search">${icon('search')}<input id="quick-query" placeholder="Search people or groups" autofocus aria-label="Search people or groups"></div><div id="quick-results"></div>`);const draw=()=>{const q=dialog.querySelector('input').value.toLowerCase();const cs=S.conversations.filter(c=>title(c).toLowerCase().includes(q));dialog.querySelector('#quick-results').innerHTML=cs.map(c=>`<button class="search-result" data-result="${e(c.id)}">${c.kind==='group'?icon('users'):avatar(other(c))}<span>${e(title(c))}</span>${icon('arrow',16)}</button>`).join('')||'<p class="muted">No conversations found.</p>';dialog.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{dialog.close();openChat(b.dataset.result);});};dialog.querySelector('input').oninput=draw;draw();}
function newGroup(){const friends=S.friends.filter(f=>f.status==='accepted');const dialog=modal('New Message',`<p>Group messages can have up to 8 members.</p><input class="full-input" id="group-name" maxlength="60" placeholder="Group name (optional)"><div class="member-picker">${friends.map(f=>`<label>${avatar(f)}<span>${e(f.name)}<small>${e(f.handle)}</small></span><input type="checkbox" value="${e(f.uid)}"></label>`).join('')||'<p>Add a friend first.</p>'}</div><footer><button class="text-button" data-cancel>Cancel</button><button class="primary" data-create disabled>Create Message</button></footer>`);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onchange=()=>{dialog.querySelector('[data-create]').disabled=!dialog.querySelector('input[type=checkbox]:checked')};dialog.querySelector('[data-create]').onclick=()=>act(async()=>{const selected=[...dialog.querySelectorAll('input:checked')].map(el=>el.value);const result=await api('/conversations',{method:'POST',body:{members:selected,name:dialog.querySelector('#group-name').value,group:selected.length>1}});dialog.close();await refresh();await openChat(result.id);});}
function openAccountPopover(){if(accountCard){closeMenu();return}closeMenu();const anchor=$('#account-dock');accountCard=accountPopover({anchor,profile:S.user,accounts:savedAccounts(S.user),edit:()=>profile(S.user.uid),setStatus:async status=>{S.user=(await api('/me',{method:'PUT',body:{status}})).user;rememberAccount(S.user).catch(()=>{});updateDock();},manage:manageAccounts,switchAccount:uid=>act(()=>activateAccount(uid)),copy:async(value,message)=>{try{if(value!==null)await navigator.clipboard.writeText(value);toast(message)}catch{toast('Clipboard access was denied.')}},onclose:()=>{accountCard=null;$('.self-profile')?.setAttribute('aria-expanded','false')}});$('.self-profile').setAttribute('aria-expanded','true');const element=accountCard.element;profiles.get(S.user.uid).then(p=>{if(!element.isConnected)return;element.querySelector('.account-popover-banner').style.background=p.banner;const info=document.createElement('div');info.className='account-profile-extra';info.innerHTML=(p.pronouns?'<p>'+e(p.pronouns)+'</p>':'')+(p.bio?'<div class="profile-bio">'+messageHTML(p.bio)+'</div>':'')+profiles.compact(p);element.querySelector('.account-popover-identity').append(info);info.querySelector('.profile-game-collection').onclick=()=>{closeMenu();profiles.full(p)};element.style.top=Math.max(8,$('#account-dock').getBoundingClientRect().top-element.offsetHeight-8)+'px';renderEmoji(info)}).catch(()=>{});}
async function activateAccount(uid){if(uid===S.user.uid)return;await movies.close();await engine?.leave();clearInterval(refreshTimer);clearTimeout(liveRetry);if(live){live.onclose=null;live.close();live=null}closeMenu();S.active=null;S.messages=[];S.view='friends';S.tab='online';layers.querySelectorAll('dialog').forEach(d=>d.close());await switchAccount(uid);}
function manageAccounts(){const accounts=savedAccounts(S.user);const dialog=modal('Manage Accounts',`<p class="manage-accounts-intro">Switch accounts, sign in, sign out.</p><div class="managed-accounts">${accounts.map(a=>`<div class="managed-account">${avatar({...a,last_seen:Date.now()})}<span><strong>${e(a.name)}</strong><small>${e(a.handle)}</small></span>${a.uid===S.user.uid?'<span class="current-account">'+icon('check',18)+'</span>':'<button class="secondary" data-switch-account="'+e(a.uid)+'">Switch</button>'}<button class="icon-button" data-account-options="${e(a.uid)}" aria-label="More options for ${e(a.handle)}">${icon('more')}</button></div>`).join('')}</div><button class="secondary wide" data-add-account>Add an account</button>`);dialog.querySelectorAll('[data-switch-account]').forEach(b=>b.onclick=()=>act(()=>activateAccount(b.dataset.switchAccount)));dialog.querySelectorAll('[data-account-options]').forEach(b=>b.onclick=()=>{const row=b.closest('.managed-account'),existing=row.querySelector('.account-options-menu');dialog.querySelectorAll('.account-options-menu').forEach(x=>x.remove());if(existing)return;const menu=document.createElement('div');menu.className='account-options-menu';menu.setAttribute('role','menu');menu.innerHTML='<button role="menuitem">Log Out</button>';row.append(menu);menu.querySelector('button').onclick=()=>act(async()=>{const uid=b.dataset.accountOptions;if(uid===S.user.uid){await engine?.leave();await api('/session',{method:'DELETE'});await forgetAccount(uid);await signOut(auth)}else{await forgetAccount(uid);dialog.close();manageAccounts()}});menu.querySelector('button').focus();});dialog.querySelector('[data-add-account]').onclick=()=>{dialog.close();addAccountDialog()};}
function addAccountDialog(){const dialog=modal('Add an account',`<form id="add-account-form"><label>USERNAME OR EMAIL<input name="handle" autocomplete="username" required></label><label>PASSWORD<input name="password" type="password" autocomplete="current-password" required></label><p class="form-error" role="alert"></p><button class="primary wide" type="submit">Log In</button></form>`);const form=dialog.querySelector('form');form.onsubmit=async ev=>{ev.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const uid=await addAccount(form.elements.handle.value.trim(),form.elements.password.value);dialog.close();await activateAccount(uid)}catch(error){form.querySelector('.form-error').textContent=error.code==='auth/invalid-credential'?'Incorrect username or password.':error.message;submit.disabled=false}};form.elements.handle.focus();}
function profile(uid){if(uid!==S.user.uid)return profiles.full(uid);const p=user(uid),self=uid===S.user.uid;const dialog=modal(self?'Your account':p.name,`<div class="profile-banner"></div><div class="profile-details">${avatar({...p,status:self?p.status:p.presence||p.status},'large')}<h1>${e(p.name)}</h1><p>@${e(p.handle)}</p>${self?`<label>DISPLAY NAME<input id="profile-name" maxlength="48" value="${e(p.name)}"></label><label>USERNAME<input id="profile-handle" maxlength="20" value="${e(p.handle)}"></label><label>PRONOUNS<input id="profile-pronouns" maxlength="40"></label><label>BIO<textarea id="profile-bio" maxlength="190"></textarea></label><label>BANNER COLOR<input id="profile-banner" type="color" value="#232428"></label><label>PROFILE PHOTO<input type="file" id="avatar-input" accept="image/png,image/jpeg,image/webp"></label><button type="button" class="secondary" id="adjust-avatar" ${p.avatar?'':'hidden'}>Adjust Image</button><p class="muted">JPG, PNG or WebP. Drag and zoom to position your photo.</p><button class="primary wide" id="save-profile">Save Changes</button>`:`<button class="primary wide" id="profile-message">Message</button>`}</div>`);if(!self){dialog.querySelector('#profile-message').onclick=()=>{dialog.close();act(()=>chatWith(uid));};return;}dialog.querySelector('#save-profile').disabled=true;for(const id of ['profile-bio','profile-pronouns','profile-banner'])dialog.querySelector('#'+id).disabled=true;profiles.get(uid).then(extra=>{if(!dialog.isConnected)return;dialog.querySelector('#profile-bio').value=extra.bio;dialog.querySelector('#profile-pronouns').value=extra.pronouns;dialog.querySelector('#profile-banner').value=extra.banner;dialog.querySelector('.profile-banner').style.background=extra.banner;dialog.querySelector('#save-profile').disabled=false;for(const id of ['profile-bio','profile-pronouns','profile-banner'])dialog.querySelector('#'+id).disabled=false;}).catch(error=>toast(error.message));dialog.querySelector('#profile-banner').oninput=ev=>dialog.querySelector('.profile-banner').style.background=ev.target.value;let changedAvatar,avatarSource=p.avatar;const previewAvatar=async source=>{try{const result=await editAvatar({source,modal});if(result){avatarSource=source;changedAvatar=result;dialog.querySelector('.profile-details>.avatar').innerHTML=`<img src="${result}" alt="Profile preview">`;dialog.querySelector('#adjust-avatar').hidden=false;}}catch(error){toast(error.message)}};dialog.querySelector('#adjust-avatar').onclick=()=>previewAvatar(avatarSource);dialog.querySelector('#avatar-input').onchange=async event=>{const f=event.target.files[0];if(!f)return;if(f.size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('Use a JPG, PNG or WebP under 10 MB.');return}const reader=new FileReader();reader.onload=async()=>{await previewAvatar(reader.result);event.target.value=''};reader.readAsDataURL(f);};dialog.querySelector('#save-profile').onclick=()=>act(async()=>{S.user=(await api('/me',{method:'PUT',body:{name:dialog.querySelector('#profile-name').value,handle:dialog.querySelector('#profile-handle').value,status:S.user.status,...(changedAvatar?{avatar:changedAvatar}:{})}})).user;await api('/profiles/'+encodeURIComponent(S.user.uid),{method:'PUT',body:{bio:dialog.querySelector('#profile-bio').value,pronouns:dialog.querySelector('#profile-pronouns').value,banner:dialog.querySelector('#profile-banner').value}});dialog.close();await refresh();toast('Account updated.');});}
