function editMessage(message){if(!message||message.sender!==S.user.uid||message.deleted)return;const article=[...document.querySelectorAll('[data-message]')].find(el=>el.dataset.message===message.id);if(!article)return;const target=article.querySelector('.message-text');const original=message.text;article.classList.add('editing-message');target.innerHTML=`<form class="inline-edit"><textarea maxlength="4000" aria-label="Edit message">${e(original)}</textarea><p>escape to <button type="button" data-edit-cancel>cancel</button> • enter to <button type="submit">save</button></p><span class="edit-error" role="alert"></span></form>`;const form=target.querySelector('form'),input=form.querySelector('textarea');const cancel=()=>{article.classList.remove('editing-message');target.innerHTML=messageHTML(original);renderEmoji(article)};form.querySelector('[data-edit-cancel]').onclick=cancel;input.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();cancel()}if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();form.requestSubmit()}};form.onsubmit=async event=>{event.preventDefault();const text=input.value.trim();if(!text)return;if(text===original)return cancel();form.querySelector('[type=submit]').disabled=true;try{await updateMessage(message.id,{text})}catch(error){form.querySelector('.edit-error').textContent=error.message;form.querySelector('[type=submit]').disabled=false}};input.focus();input.setSelectionRange(input.value.length,input.value.length);}
function reactions(id,anchor){popup(anchor,['👍','❤️','😂','😮','😢','🔥','🎉'].map(emoji=>({id:emoji,label:emoji,icon:'emoji',run:()=>updateMessage(id,{emoji})})));}
function forwardMessage(m){const dialog=modal('Forward To',`<p>Select a conversation.</p><div class="member-picker">${S.conversations.filter(c=>c.id!==S.active).map(c=>`<button class="search-result" data-destination="${e(c.id)}">${icon('chat')}<span>${e(title(c))}</span></button>`).join('')||'<p class="muted">Start another conversation first.</p>'}</div><blockquote>${e(m.text)}</blockquote>`);dialog.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>act(async()=>{await api('/conversations/'+encodeURIComponent(b.dataset.destination)+'/messages',{method:'POST',body:{id:crypto.randomUUID(),text:'Forwarded message\n'+m.text}});dialog.close();toast('Message forwarded.');}));}
