async function startCall(kind){if(!navigator.mediaDevices?.getUserMedia)throw Error('Calling requires a secure browser with microphone support.');const cid=S.active,result=await api('/conversations/'+encodeURIComponent(cid)+'/calls',{method:'POST',body:{kind}});await engine.join(result.call,result.members);sound('user_join');await refresh();}
